const memberLabel=member=>member.role==='owner'?(libraries.find(x=>x.id===library)?.personal===false?'所有者（ホスト・管理者）':'所有者'):member.is_library_admin?'共有管理者':({editor:'編集者',viewer:'閲覧者'}[member.role]||member.role);
