function errorMarkup(){if(!errorText)return '';const info=errorInfo||classifyError(errorText);return '<div class="error-summary" data-error-category="'+esc(info.category)+'"><strong>'+esc(info.title)+'</strong><p>'+esc(info.action)+'</p><details><summary>詳細</summary><pre>'+esc(redactDiagnostic(info.detail))+'</pre></details></div>'}function fail(error){errorText=error.message||String(error);errorInfo=classifyError(error);const el=document.querySelector('#cloud-error');if(el)el.innerHTML=errorMarkup();}
async function save(){const epoch=authEpoch,id=library;try{await sync.save(withoutSharedItems(bridge.snapshot()));if(epoch!==authEpoch||id!==library)return;if(!sync.dirty&&!sync.conflict){errorText='';errorInfo=null;const feedback=document.querySelector('#cloud-error');if(feedback)feedback.replaceChildren()}updateBookings();if(sync.dirty&&!sync.conflict){clearTimeout(timer);timer=setTimeout(save,800)}}catch(error){if(epoch===authEpoch&&id===library)fail(error)}}
function downloadState(){const text=JSON.stringify({version:2,...withoutSharedItems(bridge.snapshot())},null,2),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SPOOL-online-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
