function updateCloudNavigation(){const bookings=!document.querySelector('#bookingView').hidden;panel.querySelectorAll('[data-cloud-nav]').forEach(button=>{const active=(button.dataset.cloudNav==='bookings')===bookings;button.classList.toggle('is-active',active);button.setAttribute('aria-current',active?'page':'false')})}
function configure(url,key){
 const config=publicConfig({url,key},configuredOrigin);sessionStorage.removeItem('sb-'+new URL(config.url).hostname.split('.')[0]+'-auth-token');client=createClient(config.url,config.key,{global:{fetch:retryingFetch(fetch.bind(globalThis),{context:()=>authEpoch,onRetry:networkRetryNotice})},auth:{flowType:'pkce',storage:sessionStorage,storageKey:authStorageKey(config.url),persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
}

// Auth callbacks must return before Supabase requests start (the auth lock is held).
function scheduleAccountLoad(){
 const epoch=++authEpoch,userId=session.user.id;
 accountLoading=true;loading=false;errorText='';errorInfo=null;lock();render();
 setTimeout(()=>{if(epoch===authEpoch&&session?.user.id===userId)loadAccount().catch(fail)},0);
}
async function start(){
 const initialEpoch=authEpoch;
 client.auth.onAuthStateChange((event,s)=>{
  if(event==='SIGNED_OUT'){
   session=null;capabilities=rolePermissions('viewer');isAdmin=false;mobileLibraryExpanded=false;authEpoch++;sharing.clear();accountLoading=false;loading=false;
   lock();clearTimeout(timer);sync.reset(null);bridge.apply(empty());library=null;libraries=[];errorText='';errorInfo=null;render();
  }else if(s&&(!session||session.user.id!==s.user.id)){
   session=s;library=null;scheduleAccountLoad();
  }else session=s;
 });
 const {data,error}=await client.auth.getSession();
 if(error)fail(error);
 if(!session&&data.session&&initialEpoch===authEpoch){session=data.session;scheduleAccountLoad()}
 else render();
}
async function loadAccount(){
 if(!session)return;
 bridge.displayAccount(session.user.id);
 const epoch=++authEpoch;
 accountLoading=true;isAdmin=false;lock();library=null;libraries=[];errorText='';errorInfo=null;
 clearTimeout(timer);sync.reset(null);bridge.apply(empty());render();
 try{
  const [{data,error},admin]=await Promise.all([client.rpc('ensure_my_library'),client.rpc('spool_is_admin')]);if(epoch!==authEpoch)return;if(error)throw error;
  const result=await client.from('libraries').select('*').order('created_at');if(epoch!==authEpoch)return;if(result.error)throw result.error;
  libraries=result.data;
  isAdmin=!admin.error&&admin.data===true;await loadLibrary(data);
 }catch(error){if(epoch===authEpoch)fail(error)}
 finally{if(epoch===authEpoch){accountLoading=false;if(!library)render()}}
}
async function loadLibrary(id,force=false){
 if(loading||sync.busy||uploading)return;
 if(sync.dirty&&!confirm('未保存の変更があります。JSONで退避してから読み直してください。変更を破棄しますか？')){render();return;}
 const epoch=authEpoch;loading=true;lock();clearTimeout(timer);
 try {const [{data,error},membership]=await Promise.all([client.from('library_state').select('*').eq('library_id',id).single(),client.from('library_members').select('role').eq('library_id',id).eq('user_id',session.user.id).single()]);if(error)throw error;if(membership.error)throw membership.error;if(epoch!==authEpoch)return;
 capabilities=await fetchPermissions(client,id,membership.data.role);if(epoch!==authEpoch)return;const linked=bridge.apply(data.state);library=id;role=membership.data.role;sync.reset(id,data.revision);if(linked&&role!=='viewer')window.spoolOnlineChanged();await refreshSharedInventory(id);if(epoch!==authEpoch)return;errorText='';errorInfo=null;render();document.body.classList.remove('cloud-locked');document.body.classList.toggle('cloud-viewer',role==='viewer');
 for(const selector of ['#add','#addBooking','#openLibrary','#emptyAddBooking','#undoDelete','#bulkAdd','#bulkDelete','#toggleReorder'])document.querySelector(selector).disabled=role==='viewer';
 applyPermissionControls();
 void sharing.refresh().catch(error=>{if(epoch===authEpoch)fail(error)});
 }catch(error){if(epoch===authEpoch){fail(error);render()}}finally{if(epoch===authEpoch)loading=false}
}
async function loadMembers(){
 const lib=library,epoch=authEpoch;
 const response=await client.rpc('get_library_member_profiles',{lib});
 if(lib!==library||epoch!==authEpoch)return;
 let members=response.data;
 if(response.error){if(response.error.code!=='PGRST202')throw response.error;const legacy=await client.from('library_members').select('*').eq('library_id',lib);if(legacy.error)throw legacy.error;members=legacy.data.map(x=>({...x,display_name:'メンバー',display_id:''}));}
 if(lib!==library||epoch!==authEpoch)return;
 memberProfiles={library:lib,people:members};
 const labels={owner:'所有者',editor:'編集者',viewer:'閲覧者'},people=document.querySelector('#cloud-people'),list=document.querySelector('#cloud-members');
 function memberRow(member,editable){const li=document.createElement('li'),name=document.createElement('strong');name.textContent=member.display_name||'メンバー';li.append(name);const caption=document.createElement('span');caption.textContent=(member.display_id?' @'+member.display_id:'（表示ID未設定）')+' · '+memberLabel(member)+(member.user_id===session.user.id?' · 自分':'');li.append(caption);if(editable&&libraryAdmin()&&member.role!=='owner'&&libraries.find(x=>x.id===lib)?.personal===false){const permissionsButton=document.createElement('button');permissionsButton.textContent='操作権限';permissionsButton.dataset.memberPermissions=member.user_id;permissionsButton.onclick=()=>{document.querySelector('#cloud-users-dialog')?.close();editMemberPermissions(member)};li.append(permissionsButton)}if(editable&&libraryAdmin()&&member.role!=='owner'){const button=document.createElement('button');button.textContent='共有を解除';button.onclick=async()=>{const {error}=await client.rpc('remove_library_member',{lib,target_user:member.user_id});if(lib!==library||epoch!==authEpoch)return;if(error)fail(error);else loadMembers().catch(fail)};li.append(button)}return li;}
 if(people)people.replaceChildren(...members.map(x=>memberRow(x,false)));if(list)list.replaceChildren(...members.map(x=>memberRow(x,true)));
 if(!libraryAdmin())return;
 const invites=await client.from('library_invitations').select('*').eq('library_id',lib);if(lib!==library||epoch!==authEpoch)return;if(invites.error)throw invites.error;
 const pending=document.querySelector('#cloud-invites');if(!pending)return;pending.replaceChildren(...invites.data.map(invite=>{const li=document.createElement('li');li.textContent=invite.email+' — '+(labels[invite.role]||invite.role)+' ';const button=document.createElement('button');button.textContent='招待取消';button.onclick=async()=>{const {error}=await client.from('library_invitations').delete().eq('library_id',lib).eq('email',invite.email);if(lib!==library||epoch!==authEpoch)return;if(error)fail(error);else loadMembers().catch(fail)};li.append(button);return li}));if(!invites.data.length){const li=document.createElement('li');li.textContent='招待中のアカウントはありません。';pending.append(li)}
}

function updateBookings(){const select=document.querySelector('#cloud-booking');if(!select)return;const previous=select.value;select.innerHTML='<option value="">予約を選択</option>'+bridge.snapshot().reservations.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');select.value=previous;}
async function upload(e){const file=e.target.files[0],booking=document.querySelector('#cloud-booking').value,lib=library;if(!file||uploading)return;uploading=true;e.target.disabled=true;try{
 if(!can('files_upload'))throw Error('ファイルを追加する権限がありません。');if(!booking)throw Error('予約を選択してください');if(sync.dirty||sync.busy)throw Error('先に予約をオンライン保存してください');if(file.size<1||file.size>104857600||file.name.length>240||!/\.(stl|obj|3mf|amf|step|stp|gcode)$/i.test(file.name))throw Error('対応形式・100MB以下のファイルを選択してください');
 const id=crypto.randomUUID(),object_path=`${lib}/${id}/model`;const meta=await client.from('library_files').insert({id,library_id:lib,booking_id:booking,name:file.name,size:file.size,object_path});if(meta.error)throw meta.error;
 const result=await client.storage.from('spool-models').upload(object_path,file,{contentType:'application/octet-stream',upsert:false});if(result.error){await client.from('library_files').delete().eq('id',id);throw result.error}await loadFiles();
 }catch(error){fail(error)}finally{uploading=false;e.target.value='';e.target.disabled=!can('files_upload')}}
async function loadFiles(){const lib=library,booking=document.querySelector('#cloud-booking').value;const {data,error}=await client.from('library_files').select('*').eq('library_id',lib).eq('booking_id',booking);if(error)throw error;if(lib!==library)return;document.querySelector('#cloud-files').replaceChildren(...data.map(file=>{const li=document.createElement('li');li.textContent=`${file.name} (${Math.ceil(file.size/1024)} KB) `;const open=document.createElement('button');open.textContent='取得';open.onclick=async()=>{const {data,error}=await client.storage.from('spool-models').createSignedUrl(file.object_path,60,{download:file.name});if(error)fail(error);else{const a=document.createElement('a');a.href=data.signedUrl;a.rel='noopener noreferrer';a.click()}};li.append(open);if(can('files_delete')){const remove=document.createElement('button');remove.textContent='削除';remove.onclick=async()=>{if(!confirm('添付ファイルを削除しますか？'))return;const result=await client.storage.from('spool-models').remove([file.object_path]);if(result.error){fail(result.error);return}const meta=await client.from('library_files').delete().eq('id',file.id);if(meta.error)fail(meta.error);else loadFiles().catch(fail)};li.append(remove)}return li}));}
// Reservation form uploads use the same private bucket and membership policies.
window.spoolBookingFileUpload=async(bookingId,files)=>{
 if(!library||!can('files_upload')||!can('bookings_edit')||uploading)throw Error('ファイルを保存できる状態ではありません。');
 const lib=library,epoch=authEpoch,uploaded=[];uploading=true;clearTimeout(timer);
 const picker=document.querySelector('#cloud-library');if(picker)picker.disabled=true;
 try{
  for(let attempt=0;sync.busy&&attempt<150;attempt++)await new Promise(resolve=>setTimeout(resolve,100));
  if(sync.busy)throw Error('予約の保存が完了してから、もう一度お試しください。');
  await save();if(sync.dirty||sync.busy||sync.conflict)throw Error('先に予約のオンライン保存を確認してください。');
  for(const file of files){
   if(library!==lib||authEpoch!==epoch)throw Error('ログイン状態が変わりました。保存状態を確認してください。');
   if(!/\.(stl|obj|3mf|amf|step|stp|gcode)$/i.test(file.name)||file.name.length>240||file.size<1||file.size>104857600)throw Error('対応形式・100MB以下のファイルを指定してください。');
   const id=crypto.randomUUID(),object_path=`${lib}/${id}/model`;
   const meta=await client.from('library_files').insert({id,library_id:lib,booking_id:bookingId,name:file.name,size:file.size,object_path});if(meta.error)throw meta.error;
   const result=await client.storage.from('spool-models').upload(object_path,file,{contentType:'application/octet-stream',upsert:false});
   if(result.error){await client.from('library_files').delete().eq('id',id);throw result.error}
   uploaded.push({id,name:file.name,size:file.size,kind:'online'});
  }
  return uploaded;
 }catch(error){const failure=Error(error.message||'添付の保存に失敗しました。');failure.uploadedAttachments=uploaded;failure.remainingFiles=files.slice(uploaded.length);throw failure}
 finally{uploading=false;if(picker)picker.disabled=false}
};
window.spoolDownloadBookingAttachment=async id=>{if(!session||!library)throw Error('ログインして添付を取得してください。');const meta=await client.from('library_files').select('*').eq('id',id).eq('library_id',library).single();if(meta.error)throw meta.error;const result=await client.storage.from('spool-models').createSignedUrl(meta.data.object_path,60,{download:meta.data.name});if(result.error)throw result.error;const a=document.createElement('a');a.href=result.data.signedUrl;a.rel='noopener noreferrer';a.click()};

// Online uses only authenticated state; offline data-management controls are not used.
for(const id of ['#navData','#manageData','#quickSave','#saveStatusSummary'])document.querySelector(id).hidden=true;
document.querySelector('.side-bottom').textContent='オンライン共有ライブラリ';
document.querySelector('.footnote').textContent='商品ライブラリから素材を選んで登録。変更はオンラインへ自動保存されます。';
window.addEventListener('beforeunload',e=>{if(sync.dirty||uploading){e.preventDefault();e.returnValue=''}});
setInterval(async()=>{if(!library||sync.dirty||sync.busy||loading||document.querySelector('dialog[open]'))return;try{const lib=library;const {data,error}=await client.from('library_state').select('revision').eq('library_id',lib).single();if(error){lock();throw error}if(lib===library&&data.revision!==sync.revision)await loadLibrary(lib)}catch(error){fail(error)}},15000);
try{
 if(window.top!==window.self){lock();panel.innerHTML='<div class="cloud-welcome"><h1>SPOOLを直接開いてください</h1><p>安全のため、埋め込み画面ではログインできません。</p><a class="cloud-primary" href="./" target="_blank" rel="noopener noreferrer">別のタブで開く ↗</a></div>'}
 else{
  const response=await fetch('./config.json',{cache:'no-store'});if(!response.ok)throw Error('公開された接続設定を読み込めません');const supplied=await response.json();
  configuredOrigin=new URL(supplied.url).origin;let config;
  if(supplied.key){config=publicConfig(supplied);managedConfig=true;sessionStorage.removeItem('spool-online-config')}
  else{const cached=JSON.parse(sessionStorage.getItem('spool-online-config')||'null');if(cached)config=publicConfig(cached,configuredOrigin)}
  if(config){configure(config.url,config.key);await start()}else render();
 }
}catch(error){fail(error);render()}
